#include <stdio.h>

int main() {
    int rows = 4;
    for (int i = 1; i <= rows; i++) {
        for (int space = 0; space < rows - i; space++) {
            printf(" ");
        }
        for (int star = 0; star < 2 * i - 1; star++) {
            printf("*");
        }
        printf("\n");
    }
    return 0;
}
